+    h.execute(&world, AddTool::new(&world, "EM-SIX", end_mill(6.0)).expect("6 mm tool"));
+    let msg = refused(CreateOperation::new(&world, "S1", "EM-SIX", SrcRef::Stock, slot(0.5)), "6 mm tool, 0.5 mm on each wall");
