+
+#[test]
+fn a_tool_library_edit_that_widens_a_slot_cutter_is_refused() {
+    let (world, mut h) = world();
+    h.execute(&world, CreateOperation::new(&world, "S1", SMALL, SrcRef::Stock, slot(0.0)).expect("create"));
